/**
 * The action a user took in response to a `ToolCall` awaiting approval.
 *
 * - `'approve'` — the user approved the tool invocation.
 * - `'reject'` — the user rejected the tool invocation.
 */
export type ToolCallActionType = 'approve' | 'reject';
